"""Saved-only matched causal comparison of contact/proprioception deletions."""
from pathlib import Path
import json,numpy as np
R=Path('/home/sensen/Desktop/engine修复验收/s5-sensory-channel-cuts')
BASE=Path('/home/sensen/Desktop/engine修复验收/s5-fast-neural-takeover/20261028T061000Z')
def metrics(p,baseline):
 with np.load(p/'BODY.npz') as z:b={k:z[k] for k in z.files}
 a=baseline;rec=json.loads((p/'NEURAL_RECORDS.json').read_text());before=np.load(p/'HANDOVER_BEFORE.npz');ref=np.load(BASE/'HANDOVER_BEFORE.npz')
 assert set(before.files)==set(ref.files)
 for k in before.files:np.testing.assert_array_equal(before[k],ref[k])
 sw=float(before['time']);t=b['time'];j=np.flatnonzero(t>=sw-1e-9)[0]
 for k in ['time','qpos','qvel','activation']:np.testing.assert_array_equal(b[k][:j+1],a[k][:j+1])
 assert not b['assist'][j:].any() and not b['external'].any() and not b['warning'].any()
 nf=np.flatnonzero((t>=sw-1e-9)&(b['nonfoot_count']>0));late=t>=t[-1]-.2;weight=json.loads((p/'GAINS.json').read_text())['weight'];delta=np.max(abs(b['qpos']-a['qpos']),axis=1);di=np.flatnonzero(delta>1e-12)
 applied=next((r['relative_start_s'] for r in rec if np.any(r['applied_command'])),None)
 return dict(directory=str(p),warmup_and_handover_exact=True,first_nonfoot_relative_s=None if not len(nf) else float(t[nf[0]]-sw),first_applied_command_s=applied,motor_spikes_first15ms=sum(r['motor_spikes'] for r in rec if r['relative_start_s']<.015),motor_spikes_total=sum(r['motor_spikes'] for r in rec),total_network_spikes_first15ms=sum(r['total_network_spikes'] for r in rec if r['relative_start_s']<.015),total_network_spikes=sum(r['total_network_spikes'] for r in rec),first_body_divergence_vs_baseline_s=None if not len(di) else float(t[di[0]]-sw),last200ms_foot_load_ratio=float(b['foot_force'][late,:,2].sum(1).mean()/weight),last200ms_nonfoot_fraction=float(np.mean(b['nonfoot_count'][late]>0)),final_com_height=float(b['com'][-1,2]),sensory_current_min_nA=min(r['sensory_current_min_nA'] for r in rec),sensory_current_max_nA=max(r['sensory_current_max_nA'] for r in rec),counts=json.loads((p/'EXECUTION.json').read_text())['counts'])
def main():
 with np.load(BASE/'BODY.npz') as z:a={k:z[k] for k in z.files}
 rows=[metrics(BASE,a)]+[metrics(R/f'20261028T{v:03}000Z',a) for v in [68,69]]
 out=dict(scope='Three matched real250ms neural continuations: reference, cutcontact, cutproprio. No simulated commands generated by this comparison. Behavioral success not inferred from spiking.',runs=rows)
 (R/'SENSORY_CUT_COMPARISON.json').write_text(json.dumps(out,indent=2)+'\n');print(json.dumps(out,indent=2))
if __name__=='__main__':main()
